// Garante que a rota triagem devolva JSON *parseavel*. O Intra ja valida os
// valores (campo.ts -> umaDe), mas se o corpo nao for JSON ele cai no plano B e
// abre a pendencia com a etiqueta sem-classificacao-ia. Modelo que responde com
// cerca de codigo custaria justamente isso.
const CATEGORIAS = ['rede', 'email', 'impressora', 'hardware', 'software', 'acesso',
  'backup', 'servidor', 'seguranca', 'telefonia', 'outro'];
const PRIORIDADES = ['baixa', 'media', 'alta'];  // critica nao: o teto da triagem e alta
const TIPOS = ['Projeto', 'Operacional / Interno', 'Manutenção', 'Suporte', 'Gestão', 'Outro'];

const bruto = String($json.text ?? $json.response ?? '').trim();
const semCerca = bruto.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const ini = semCerca.indexOf('{');
const fim = semCerca.lastIndexOf('}');

let j = null;
if (ini !== -1 && fim > ini) {
  try { j = JSON.parse(semCerca.slice(ini, fim + 1)); } catch (e) { j = null; }
}

// Nao deu para entender a resposta: estourar e o certo. O webhook responde 500,
// o Intra trata como falha da IA e abre o chamado com a etiqueta
// sem-classificacao-ia — o aviso de "confira isto antes de responder".
// Devolver um objeto vazio e valido seria pior: o chamado pareceria
// classificado, sem ninguem ter classificado nada.
if (!j || typeof j !== 'object' || Array.isArray(j)) {
  throw new Error('A rota triagem nao devolveu JSON: ' + bruto.slice(0, 200));
}

const texto = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const umaDe = (v, lista, padrao) => {
  const alvo = texto(v, 60).toLowerCase();
  return lista.find((x) => x.toLowerCase() === alvo) ?? padrao;
};

// "critica" nao e invalida, e acima do teto: rebaixa para alta, como o Intra
// faz em campo.ts. Mandar para o padrao "media" perderia a urgencia do e-mail.
const prioridade = texto(j.prioridade, 60).toLowerCase() === 'critica'
  ? 'alta'
  : umaDe(j.prioridade, PRIORIDADES, 'media');

return [{
  json: {
    assunto: texto(j.assunto, 140),
    descricao: texto(j.descricao, 600),
    categoria: umaDe(j.categoria, CATEGORIAS, 'outro'),
    prioridade,
    tipo: umaDe(j.tipo, TIPOS, 'Suporte'),
    solicitante: texto(j.solicitante, 120),
    ignorar: j.ignorar === true || texto(j.ignorar, 10).toLowerCase() === 'true',
  },
}];
